  document.getElementById('contactForm').addEventListener('submit', (e) => {
    e.preventDefault();

    // Touch all fields
    Object.keys(fields).forEach((id) => {
      touched[id] = true;
    });

    const allValid = Object.keys(fields).every((id) => validateField(id));

    if (!allValid) {
      // Focus the first errored field
      const firstError = Object.keys(fields).find((id) => {
        return fields[id].validate(getInput(id).value) !== null;
      });
      if (firstError) getInput(firstError).focus();
      return;
    }

    // Simulate submission
    const btn = document.getElementById('submitBtn');
    btn.disabled = true;
    btn.textContent = 'Sending…';

    setTimeout(() => {
      btn.disabled = false;
      btn.textContent = 'Send Message';

